        os.makedirs(temp_dir)
    dest_script = os.path.join(temp_dir, os.path.basename(script_path))
    shutil.copy(script_path, dest_script)
    original_cwd = os.getcwd()
    os.chdir(temp_dir)
    try:
        result = subprocess.run(['python', dest_script], capture_output=True, text=True)
        if result.returncode == 0:
